// le ciocche dei capelli si disegnano qui, per tenere il file leggero
function ciocche(svg) {
  return svg.replace(/<g data-st="([^"]+)"\/>/g, (m, a) => {
    const [cx0, seed, hl, dk] = a.split(","); const cx = +cx0; let s = +seed; const o = [];
    const rnd = (lo, hi) => { s = Number((BigInt(s) * 1103515245n + 12345n) % 2147483648n); return lo + s % (hi - lo + 1); };
    for (let i = 0; i < 34; i++) {
      const an = Math.PI * (0.05 + 0.9 * i / 33), L = rnd(150, 330);
      const ex = Math.floor(cx - Math.cos(an) * L + .5), ey = Math.floor(150 + Math.sin(an) * L * .9 + .5);
      const mx = Math.floor(cx - Math.cos(an) * L * .45 + rnd(-14, 14) + .5), my = Math.floor(150 + Math.sin(an) * L * .3 - 20 + .5);
      const w = [1.5, 2, 2.5][rnd(0, 2)], c = i % 3 === 0 ? hl : dk;
      o.push(`<path d="M${cx},150 Q${mx},${my} ${ex},${ey}" stroke="${c}" stroke-width="${w}" fill="none" opacity="${i % 3 === 0 ? 0.45 : 0.35}"/>`);
    }
    return o.join("");
  });
}
export async function caricaRitratti() {
  if (typeof DecompressionStream === "undefined") return {};
  const bytes = Uint8Array.from(atob(RZ), c => c.charCodeAt(0));
  const text = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  const r = JSON.parse(text); for (const k in r) r[k] = ciocche(r[k]); return r;
}
